```js
async function resolveUser(_source, { id }, context) {
  const { rows } = await context.postgres.query(
    'SELECT id, name FROM users WHERE id = $1', [id],
  );
  return rowToUser(rows[0]);
}

async function resolvePosts(user, _args, context) {
  const { rows } = await context.postgres.query(
    'SELECT id, title FROM posts WHERE user_id = $1 ORDER BY id', [user.id],
  );
  return rows.map((row) => ({ id: String(row.id), title: row.title }));
}

async function resolveProfile(user, _args, context) {
  return context.mongo.collection('profiles').findOne(
    { _id: Number(user.id) },
    { projection: { _id: 0, theme: 1, favoriteEditor: 1 } },
  );
}

async function resolveFollows(user, _args, context) {
  const { records } = await context.graph.executeQuery(
    `MATCH (:Person {userId: $userId})-[follow:FOLLOWS]->(neighbor:Person)
     RETURN neighbor.userId AS userId
     ORDER BY follow.position`,
    { userId: user.id },
  );
  const ids = records.map((record) => record.get('userId'));
  if (ids.length === 0) return [];

  const { rows } = await context.postgres.query(
    'SELECT id, name FROM users WHERE id = ANY($1::int[])',
    [ids.map(Number)],
  );
  const usersById = new Map(rows.map((row) => [String(row.id), rowToUser(row)]));
  return ids.map(String).map((id) => usersById.get(id)).filter(Boolean);
}
```

GraphQL is a typed API query and execution layer that coordinates access to underlying services and databases; it does not replace relational, document, or graph storage engines. A list-of-users query can cause an N+1 problem when each user's `posts`, `profile`, or `follows` resolver performs its own lookup. Use a request-scoped DataLoader to batch and cache those field lookups. This keeps storage-specific querying in the resolvers while presenting one client-facing schema.

```sql
UPDATE job_postings_raw
SET company_name = 'Acme Technologies'
WHERE company_name = 'Acme Corp';

CREATE TABLE companies (
  id SERIAL PRIMARY KEY,
  name TEXT NOT NULL UNIQUE
);

CREATE TABLE cities (
  id SERIAL PRIMARY KEY,
  name TEXT NOT NULL UNIQUE
);

CREATE TABLE job_categories (
  id SERIAL PRIMARY KEY,
  name TEXT NOT NULL UNIQUE
);

CREATE TABLE job_postings (
  id INTEGER PRIMARY KEY,
  title TEXT NOT NULL,
  company_id INTEGER NOT NULL REFERENCES companies(id),
  city_id INTEGER NOT NULL REFERENCES cities(id),
  category_id INTEGER NOT NULL REFERENCES job_categories(id)
);

INSERT INTO companies (name)
SELECT DISTINCT company_name FROM job_postings_raw;

INSERT INTO cities (name)
SELECT DISTINCT city FROM job_postings_raw;

INSERT INTO job_categories (name)
SELECT DISTINCT category FROM job_postings_raw;

INSERT INTO job_postings (id, title, company_id, city_id, category_id)
SELECT raw.id, raw.title, company.id, city.id, category.id
FROM job_postings_raw AS raw
JOIN companies AS company ON company.name = raw.company_name
JOIN cities AS city ON city.name = raw.city
JOIN job_categories AS category ON category.name = raw.category;

UPDATE companies
SET name = 'Acme Corp Inc'
WHERE name = 'Acme Technologies';
```

The denormalized rename changes five raw rows. After migration, the final rename changes exactly one lookup row, while the five related normalized postings retain their foreign keys unchanged.
